/*@!Encoding:936*/      // 指定源文件编码，中文注释必加，否则乱码
includes
{
  // 引入其他 .can 文件
}

variables
{
  msTimer myTimer;     // 定时器变量
  message 0x100 msg;   // 报文变量
}

on start               // 测量启动时执行一次
{
  write("CAPL 已加载");
}

variables { msTimer doorTimer; }

on key 's' { setTimer(doorTimer, 1000); }

on timer doorTimer {
  message DoorState doormsg;
  doormsg.Door_L = 1;   // 左门开
  doormsg.Door_R = 1;   // 右门开
  output(doormsg);      // 发送到总线
  setTimer(doorTimer, 1000);  // 复位定时器→周期发送
}

// 面板滑块 EngineSpeedEntry 变化时
on sysvar Engine::EngineSpeedEntry {
  if (@Engine::EngineStateSwitch)        // 引擎已开
    $EngineState::EngineSpeed = @this;    // 滑块值→信号
}

// Display 节点收到引擎状态报文后更新仪表
on message EngineState {
  @Engine::EngineSpeedDspMeter = $EngineState::EngineSpeed / 1000.0;
}

// 车门状态：用位运算把两个信号编码成一个环境变量
on message DoorState {
  @EnvDoorState = this.Door_L + this.Door_R * 2;  // 0关 1左 2右 3全开
}

