on message 0x200 // 门状态报文ID
{
 if (this.Door_L == 1 || this.Door_R == 1)
 {
 doorOpenCount++;
 write("左车门或右车门打开，次数：%d", doorOpenCount);
 }
}

on key 'a'
{
 // 按A键模拟开门
 msgDoor.Door_L = 1;
 output(msgDoor);
}
