```Plain Text
variables
{
 int testPass = 0;
 int testFail = 0;
}

on start
{
 // 测试1：验证发动机启动信号
 setSignal(Engine_Start, 1);
 if (getSignal(Engine_RPM) > 0)
 {
 write("测试1 PASS: 发动机启动成功");
 testPass++;
 }
 else
 {
 write("测试1 FAIL: 发动机启动失败");
 testFail++;
 }

 // 测试2：验证车门未关报警
 setSignal(Door_Open, 1);
 if (getSignal(Door_Warning) == 1)
 {
 write("测试2 PASS: 车门报警正常");
 testPass++;
 }
 else
 {
 write("测试2 FAIL: 车门报警异常");
 testFail++;
 }

 write("测试完成: 通过=%d, 失败=%d", testPass, testFail);
}
